// Generated by Unremote: an MCP server for one app's private API. Tools come from unremote.config.json.
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { z } from 'zod';
import { Client, loadConfig } from './client.mjs';

const dir = path.dirname(fileURLToPath(import.meta.url));
const cfg = loadConfig(dir);
const client = new Client(cfg);
const server = new McpServer({ name: 'unremote-' + cfg.name, version: '0.1.0' });

// Real app replies can be huge (a news feed, a whole article). Agents need the gist, so large replies are
// trimmed: long lists keep their first items, long strings are cut, HTML becomes plain text.
const LIMIT = +(process.env.UNREMOTE_MAX_CHARS || 12000);
const stripHtml = s => s.replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
function prune(v, items, chars, depth = 0) {
  if (typeof v === 'string') return v.length > chars ? v.slice(0, chars) + '…' : v;
  if (Array.isArray(v)) {
    const out = v.slice(0, items).map(x => prune(x, items, chars, depth + 1));
    if (v.length > items) out.push(`… ${v.length - items} more`);
    return out;
  }
  if (v && typeof v === 'object') {
    if (depth > 6) return '…';
    return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, prune(x, items, chars, depth + 1)]));
  }
  return v;
}
function compact(data) {
  if (typeof data === 'string') {
    const text = /<\w+[^>]*>/.test(data) ? stripHtml(data) : data;
    return text.length > LIMIT ? text.slice(0, LIMIT) + `… [trimmed ${text.length - LIMIT} chars]` : text;
  }
  let text = JSON.stringify(data);
  if (text.length <= LIMIT) return JSON.stringify(data, null, 1);
  for (const [items, chars] of [[20, 600], [10, 300], [6, 160], [4, 100], [3, 60]]) {
    text = JSON.stringify(prune(data, items, chars));
    if (text.length <= LIMIT) return text + '\n[large reply trimmed]';
  }
  return text.slice(0, LIMIT) + '… [trimmed]';
}

const zodFor = inp => {
  const base = {
    string: z.string(), integer: z.number().int(), number: z.number(), boolean: z.boolean(),
    'string[]': z.array(z.string()), 'integer[]': z.array(z.number().int()),
  }[inp.type] || z.string();
  const t = base.describe(inp.description || inp.name);
  return inp.required === false ? t.optional() : t;
};

for (const tool of cfg.tools) {
  const shape = Object.fromEntries((tool.inputs || []).map(i => [i.name, zodFor(i)]));
  const write = tool.effect === 'write';
  server.registerTool(tool.name, {
    description: (write ? '[Changes state — confirm with the user first] ' : '') + tool.description,
    inputSchema: shape,
    annotations: { readOnlyHint: !write, destructiveHint: write, openWorldHint: true },
  }, async args => {
    try {
      const r = await client.call(tool, args);
      const text = compact(r.data);
      return { content: [{ type: 'text', text: r.status >= 400 ? `HTTP ${r.status}: ${text}` : text }], isError: r.status >= 400 };
    } catch (e) {
      return { content: [{ type: 'text', text: String(e.message || e) }], isError: true };
    }
  });
}

await server.connect(new StdioServerTransport());
